<?php
declare(strict_types=1);

final class PlanetDefenseService
{
    public function __construct(private PDO $pdo) {}

    private function setting(string $key,int $default=0): int{$s=$this->pdo->prepare('SELECT setting_value FROM game_settings WHERE setting_key=?');$s->execute([$key]);$v=$s->fetchColumn();return $v===false?$default:max(0,(int)$v);}
    private function event(int $playerId,int $planetId,string $type,array $payload):void{$s=$this->pdo->prepare('INSERT INTO game_events(player_id,event_type,entity_type,entity_id,payload) VALUES(?,?,?,?,?)');$s->execute([$playerId,$type,'planet',$planetId,json_encode($payload,JSON_THROW_ON_ERROR)]);}

    public function snapshot(int $playerId): array
    {
        if($playerId<1)throw new InvalidArgumentException('Invalid defense request.');$sql="SELECT pp.id planet_id,pp.player_id,pp.name planet_name,pp.defense_bonus,COALESCE(SUM(pd.level),0) structures,COALESCE(SUM(pd.strength),0) structure_strength,COALESCE(AVG(CASE WHEN pd.level>0 THEN LEAST(1.000,pd.strength/(pd.level*100)) ELSE 1 END),1.000) condition_factor,COALESCE(us.defense_power,0) garrison_power,COALESCE(pr.defense_units,0) garrison_units,COALESCE((SELECT MAX(pt.level) FROM player_technologies pt WHERE pt.player_id=pp.player_id AND (pt.technology_key='fortification' OR pt.technology_name LIKE '%Fortification%')),0) fortification_level FROM player_planets pp LEFT JOIN planet_defenses pd ON pd.planet_id=pp.id LEFT JOIN player_unit_stats us ON us.player_id=pp.player_id LEFT JOIN player_resources pr ON pr.player_id=pp.player_id WHERE pp.player_id=? GROUP BY pp.id,pp.player_id,pp.name,pp.defense_bonus,us.defense_power,pr.defense_units ORDER BY pp.id";$s=$this->pdo->prepare($sql);$s->execute([$playerId]);$rows=$s->fetchAll(PDO::FETCH_ASSOC);foreach($rows as &$row){$tech=1+((int)$row['fortification_level']*0.05);$planet=1+((float)$row['defense_bonus']/100);$row['structures']=(int)$row['structures'];$row['structure_strength']=(int)$row['structure_strength'];$row['condition_factor']=round((float)$row['condition_factor'],3);$row['technology_modifier']=round($tech,3);$row['planet_bonus']=round($planet,3);$row['shield_integrity']=(int)round((float)$row['structure_strength']*(float)$row['condition_factor']);$row['garrison_power']=(int)$row['garrison_power'];$row['garrison_units']=(int)$row['garrison_units'];$row['defense_rating']=(int)round($row['shield_integrity']*$tech*$planet);$q=$this->pdo->prepare("SELECT id,queue_type AS item_key,level_before,level_after,starts_at,completes_at,status FROM production_queues WHERE player_id=? AND queue_type='defense' AND status IN ('queued','processing') ORDER BY completes_at");$q->execute([$playerId]);$row['upgrade_queue']=$q->fetchAll(PDO::FETCH_ASSOC);}$states=['ready','empty','insufficient-resource','success','error'];return ['state'=>$rows?'ready':'empty','planets'=>$rows,'formula'=>'defense rating = structures × condition × technology × planet bonus','states'=>$states];
    }

    public function upgrade(int $playerId,int $planetId,string $defenseType): array
    {
        if($playerId<1||$planetId<1||!preg_match('/^[A-Za-z0-9_-]{2,80}$/',$defenseType))throw new InvalidArgumentException('Invalid defense input.');$this->pdo->beginTransaction();try{$cooldown=$this->setting('planet_defense_cooldown_seconds');$c=$this->pdo->prepare("SELECT available_at FROM player_cooldowns WHERE player_id=? AND cooldown_key='planet_defense' FOR UPDATE");$c->execute([$playerId]);$available=$c->fetchColumn();if($available!==false&&new DateTimeImmutable((string)$available)>new DateTimeImmutable('now'))throw new RuntimeException('Planet defense upgrade is on cooldown.');$p=$this->pdo->prepare('SELECT id,name FROM player_planets WHERE id=? AND player_id=? FOR UPDATE');$p->execute([$planetId,$playerId]);if(!$p->fetch())throw new RuntimeException('Planet not owned.');$q=$this->pdo->prepare("SELECT COUNT(*) FROM production_queues WHERE player_id=? AND queue_type='defense' AND status IN ('queued','processing') FOR UPDATE");$q->execute([$playerId]);if((int)$q->fetchColumn()>=3)throw new RuntimeException('Defense upgrade queue is full.');$d=$this->pdo->prepare('SELECT id,level,strength FROM planet_defenses WHERE planet_id=? AND defense_type=? FOR UPDATE');$d->execute([$planetId,$defenseType]);$current=$d->fetch(PDO::FETCH_ASSOC);$before=$current?(int)$current['level']:0;$max=25;if($before>=$max)throw new RuntimeException('Defense level cap reached.');$cost=10000*($before+1);$deuteriumCost=500*($before+1);$r=$this->pdo->prepare('SELECT naquadah,deuterium FROM player_resources WHERE player_id=? FOR UPDATE');$r->execute([$playerId]);$resources=$r->fetch(PDO::FETCH_ASSOC)?:[];if((int)($resources['naquadah']??0)<$cost)throw new RuntimeException('Not enough Naquadah.');if((int)($resources['deuterium']??0)<$deuteriumCost)throw new RuntimeException('Not enough Deuterium.');$this->pdo->prepare('UPDATE player_resources SET naquadah=naquadah-?,deuterium=deuterium-? WHERE player_id=?')->execute([$cost,$deuteriumCost,$playerId]);if($current){$this->pdo->prepare('UPDATE planet_defenses SET level=level+1,strength=strength+100 WHERE id=?')->execute([(int)$current['id']]);}else{$this->pdo->prepare('INSERT INTO planet_defenses(planet_id,defense_type,level,strength) VALUES(?,?,1,100)')->execute([$planetId,$defenseType]);}$seconds=300+($before*60);$start=(new DateTimeImmutable('now'))->format('Y-m-d H:i:s');$complete=(new DateTimeImmutable('now'))->modify('+'.$seconds.' seconds')->format('Y-m-d H:i:s');$this->pdo->prepare("INSERT INTO production_queues(player_id,queue_type,level_before,level_after,deuterium_cost,starts_at,completes_at,status) VALUES(?,'defense',?,?,?,?,?, 'queued')")->execute([$playerId,$before,$before+1,$deuteriumCost,$start,$complete]);$queueId=(int)$this->pdo->lastInsertId();if($cooldown>0){$next=(new DateTimeImmutable('now'))->modify('+'.$cooldown.' seconds')->format('Y-m-d H:i:s');$this->pdo->prepare("INSERT INTO player_cooldowns(player_id,cooldown_key,available_at) VALUES(?,?,?) ON DUPLICATE KEY UPDATE available_at=VALUES(available_at)")->execute([$playerId,'planet_defense',$next]);}$this->event($playerId,$planetId,'planet_defense_upgraded',['defense_type'=>$defenseType,'level_before'=>$before,'level_after'=>$before+1,'cost'=>$cost,'deuterium_cost'=>$deuteriumCost,'queue_id'=>$queueId,'queue_seconds'=>$seconds,'cooldown_seconds'=>$cooldown]);$this->pdo->commit();return ['state'=>'success','planet_id'=>$planetId,'defense_type'=>$defenseType,'level_before'=>$before,'level_after'=>$before+1,'cost'=>$cost,'deuterium_cost'=>$deuteriumCost,'queue_id'=>$queueId,'queue_seconds'=>$seconds,'cooldown_seconds'=>$cooldown];}catch(Throwable $e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw $e;}
    }
}
